func SpecTrailerCommits(root, slug string) ([]string, error) {
	out, err := RawHistoryGit(root, SpecTrailerLogArgs...).Output()
	if err != nil {
		return nil, err
	}
	return ParseSpecTrailerLog(out)[slug], nil
